    def ok_package_initialize(self, params, paramsheader):
        self.ok_package = Package()
        self.ok_package.message_in.body = params
        self.ok_package.message_in.header = paramsheader
        self.ok_package.status = Package.OK

    def error_package_initialize(self, params, paramsheader):
        self.error_package = Package()
        self.error_package.message_in.body = params
        self.error_package.message_in.header = paramsheader
        self.error_package.status = Package.OK

    #---------- Unit Test ---------- #
    def test_init(self):
        self.initialize()
        self.assertTrue(
            self.test_validations.validate_data
        )
        self.assertTrue(
            self.test_validations.config
        )

    def test_call_ok(self):
        self.initialize()
        i = len(self.params_ok)
        x = 0
        while x < i:
            self.ok_package_initialize(self.params_ok[x], self.params_ok_header[x])
            package = self.test_validations.__call__(self.ok_package)
            self.assertEqual(
                package.desc_status,
                ''
            )

            self.assertEqual(
                package.status,
                Package.OK
            )

            self.assertEqual(
                type(package.message_in.body),
                list
            )

            self.assertEqual(
                type(package.message_in.header),
                dict
            )

            if x in(0, 2, 4, 6, 7, 8, 9, 10, 11):
                self.assertEqual(
                    package.message_in.header['messages']['messagesIn'],
                    1
                )

                self.assertEqual(
                    package.message_in.header['messages']['messagesFilter'],
                    0
                )

                self.assertEqual(
                    package.message_in.header['messages']['messagesError'],
                    0
                )

            if x in (1, 3, 5, 12):
                self.assertEqual(
                    package.message_in.header['messages']['messagesIn'],
                    1
                )

                self.assertEqual(
                    package.message_in.header['messages']['messagesError'],
                    0
                )

            x += 1

    def test_call_error(self):
        self.initialize()
        i = len(self.params_error)
        x = 0
        while x < i:
            self.error_package_initialize(self.params_error[x], self.params_error_header[x])
            package = self.test_validations.__call__(self.error_package)

            self.assertEqual(
                package.message_in.header['messages']['messagesIn'],
                1
            )

            self.assertEqual(
                package.message_in.header['messages']['messagesFilter'],
                0
            )

            x += 1

    def test_process_data(self):

        self.initialize()
        response = []

        for idx in range(0, len(self.publish_order)):
            self.ok_package_initialize(self.params_ok[idx], self.params_ok_header[idx])
            self.test_validations.process_data(
                self.publish_order[idx],
                response,
                self.ok_package
            )

    def test_set_structure(self):
        self.initialize()

        for idx in range(0, len(self.data_set_structure)):
            self.ok_package_initialize(self.params_ok[0], self.params_ok_header[0])
            self.data_set_structure[idx]['releaseLine'] = {
                'itemId': '1234'
            }
            structure = self.test_validations.set_structure(
                [self.data_set_structure[idx]],
                self.data_set_structure[idx].get('orderLine'),
                self.ok_package
            )

            if idx in (0, 1, 2):
                self.assertEqual(
                    len(self.allocated),
                    len(structure)
                )

                for key_h in self.allocated:
                    for key in key_h:
                        self.assertTrue(
                            key in structure[0]
                        )

            if idx == 3:
                self.assertEqual(
                    len([self.cancelled_confirm]),
                    len(structure)
                )

                for key_h in self.cancelled_confirm:
                    self.assertTrue(
                        key_h in structure[0]
                    )

            if idx in (4, 5):
                self.assertEqual(
                    len([self.released_and_fulfilled]),
                    len(structure)
                )

                for key_h in self.released_and_fulfilled:
                    self.assertTrue(
                        key_h in structure[0]
                    )

            if idx == 6:
                self.assertEqual(
                    len(structure),
                    0
                )
                self.assertEqual(
                    structure,
                    []
                )

            self.assertEqual(
                type(structure),
                list
            )

