    def test_structure_fulfilled(self):
        self.initialize()

        for idx in range(0, len(self.data_structure_fulfilled)):
            data = self.test_validations.build_structure(
                [self.data_structure_fulfilled[idx]],
                self.data_structure_fulfilled[idx].get('orderLine')
            )

            self.assertEqual(
                len([self.released_and_fulfilled]),
                len(data)
            )

            for key_h in self.released_and_fulfilled:
                self.assertTrue(
                    key_h in data[0]
                )

            self.assertEqual(
                type(data),
                list
            )

            self.assertEqual(
                data[0].get('IntegerCancelledQuantityRelease'),
                '1'
            )
            self.assertEqual(
                data[0].get('DecimalCancelledQuantityRelease'),
                '0'
            )
            self.assertEqual(
                data[0].get('IntegerFulfilledQuantityRelease'),
                '2'
            )
            self.assertEqual(
                data[0].get('DecimalFulfilledQuantityRelease'),
                '0'
            )
            self.assertEqual(
                data[0].get('IntegerQuantityRelease'),
                '3'
            )
            self.assertEqual(
                data[0].get('DecimalQuantityRelease'),
                '0'
            )

            if idx in (0, 1):
                self.assertEqual(
                    data[0].get('ShipFromLocationId'),
                    ''
                )
                self.assertEqual(
                    data[0].get('IntegerQuantity'),
                    '2'
                )
                self.assertEqual(
                    data[0].get('DecimalQuantity'),
                    '0'
                )

            if idx == 2:
                self.assertEqual(
                    data[0].get('ShipFromLocationId'),
                    '0033'
                )
                self.assertEqual(
                    data[0].get('IntegerQuantity'),
                    '8'
                )
                self.assertEqual(
                    data[0].get('DecimalQuantity'),
                    '0'
                )

            if idx == 3:
                self.assertEqual(
                    data[0].get('ShipFromLocationId'),
                    '0033'
                )
                self.assertEqual(
                    data[0].get('IntegerQuantity'),
                    '0'
                )
                self.assertEqual(
                    data[0].get('DecimalQuantity'),
                    '0'
                )

